const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  // Repeated equal amount returns original receipt, one debit.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, { acknowledge: async () => {} });
    const a = await svc.pay('t', 'k', 5);
    const b = await svc.pay('t', 'k', 5);
    assert.deepEqual(a, b);
    assert.equal(ledger.entries.length, 1);
  }
  // Concurrent equal calls: one debit, same receipt.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, { acknowledge: async () => { await new Promise(r => setTimeout(r, 5)); } });
    const rs = await Promise.all([svc.pay('t', 'k', 5), svc.pay('t', 'k', 5), svc.pay('t', 'k', 5)]);
    assert.equal(ledger.entries.length, 1);
    assert.deepEqual(rs[0], rs[1]); assert.deepEqual(rs[1], rs[2]);
  }
  // Same key, different amount: key conflict, no second debit.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, { acknowledge: async () => {} });
    await svc.pay('t', 'k', 5);
    await assert.rejects(svc.pay('t', 'k', 6), /^Error: key conflict$/);
    assert.equal(ledger.entries.length, 1);
  }
  // Scoping: same key different tenant is a separate debit; no key collision across tenants.
  {
    const ledger = new Ledger();
    const svc = new PaymentService(ledger, { acknowledge: async () => {} });
    await svc.pay('a', 'b|c', 5);
    await svc.pay('a|b', 'c', 7);
    await svc.pay('a', 'k', 1);
    await svc.pay('b', 'k', 2);
    assert.equal(ledger.entries.length, 4);
  }
  // Transient ack after commit retries with the same receipt; one debit.
  {
    const ledger = new Ledger();
    const seen = [];
    let calls = 0;
    const svc = new PaymentService(ledger, { acknowledge: async r => {
      seen.push(r); if (++calls < 3) throw new Transient('x');
    } });
    const r = await svc.pay('t', 'k', 9, 3);
    assert.equal(calls, 3); assert.equal(ledger.entries.length, 1);
    for (const s of seen) assert.deepEqual(s, r);
  }
  // Exhausted retries rethrow the last Transient.
  {
    const ledger = new Ledger();
    let n = 0;
    const err = new Transient('final');
    const svc = new PaymentService(ledger, { acknowledge: async () => { n++; throw n === 2 ? err : new Transient('early'); } });
    await assert.rejects(svc.pay('t', 'k', 9, 2), e => e === err);
    assert.equal(n, 2); assert.equal(ledger.entries.length, 1);
  }
  // Non-Transient errors are not retried.
  {
    const ledger = new Ledger();
    let n = 0;
    const boom = new Error('boom');
    const svc = new PaymentService(ledger, { acknowledge: async () => { n++; throw boom; } });
    await assert.rejects(svc.pay('t', 'k', 9, 5), e => e === boom);
    assert.equal(n, 1);
  }
  // Invalid input throws before any ledger or transport action.
  {
    let touched = 0;
    const ledger = new Ledger();
    const origApply = ledger.apply.bind(ledger);
    ledger.apply = async (...a) => { touched++; return origApply(...a); };
    const svc = new PaymentService(ledger, { acknowledge: async () => { touched++; } });
    const bad = [
      ['', 'k', 1, 3], ['t', '', 1, 3], [undefined, 'k', 1, 3], ['t', 'k', 0, 3], ['t', 'k', 1.5, 3],
      ['t', 'k', -1, 3], ['t', 'k', 1, 0], ['t', 'k', 1, 6], ['t', 'k', 1, 1.5], ['t', 'k', 1, '2'],
    ];
    for (const args of bad) {
      await assert.rejects(svc.pay(...args), /^Error: invalid payment$/, JSON.stringify(args));
    }
    assert.equal(touched, 0);
    assert.equal(ledger.entries.length, 0);
  }
  console.log('idempotency checks OK');
}
module.exports = main();

